// Sibling files are type imports only: each script is compiled standalone, so runtime imports of them wouldn't resolve.
import { readFileSync } from "node:fs";

import type { WidgetContext, WidgetFieldValue, WidgetMount, WidgetQueryResult } from "../_lib/widget_context";

// Who's on a Palworld server, out of how many it takes. The card folds back to the plain one while
// nobody is, as Minecraft's and Valheim's do.
//
// Everything live comes from the server's REST API, which the script turns on at the port it
// publishes first (RESTAPIEnabled, RESTAPIPort): GET /v1/api/players names who's on, and
// /v1/api/metrics gives the limit (maxplayernum). It asks for HTTP basic auth as admin with the
// server's admin password. A widget never sees the install's answers, so the password, the port
// and the server's name come from the server's own PalWorldSettings.ini, where the chart's setup
// writes them before every start:
//   OptionSettings=(RESTAPIPort=30443,RESTAPIEnabled=True,AdminPassword="...",ServerName="HexOS Palworld Server",...)
// The password is only ever sent to the server itself; the card never shows it and the script never
// logs it.
//
// The file sits in the server's folder on the Media location. A box whose HexOS container can't see
// that folder has it read out of the app's container instead, over the daemon socket the HexOS
// container has for its host commands. Without the file, or with the API off, the card stays plain.

const SETTINGS = "/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini";
const SERVER_DIR = "/serverdata/serverfiles";
const DOCKER_SOCKET = "/var/run/docker.sock";
/** Docker and the API share the widget's 5 s timeout, so a stuck one reads as nothing rather than failing the card. */
const DOCKER_TIMEOUT_MS = 1500;
const API_TIMEOUT_MS = 2500;
/** Palworld's own default, when neither the API nor the file says. */
const DEFAULT_REST_PORT = 8212;

/** The server's folder, by its host path, since the chart mounts it itself. A later copy's ends in -2. */
export const serverMount = (mounts: WidgetMount[]): WidgetMount | undefined =>
  mounts.find((m) => m.containerPath === SERVER_DIR) ?? mounts.find((m) => /\/palworld(-\d+)?$/.test(m.hostPath));

/**
 * The OptionSettings line of PalWorldSettings.ini as a map. It's Unreal's text for a struct: a
 * quoted value may hold commas and escaped quotes, and a value in parentheses may hold a list.
 */
export function optionSettings(text: string): Map<string, string> {
  const found = new Map<string, string>();
  const line = /^\s*OptionSettings\s*=\s*\((.*)\)\s*$/m.exec(text)?.[1] ?? "";
  let at = 0;
  while (at < line.length) {
    const equals = line.indexOf("=", at);
    if (equals < 0) break;
    const key = line.slice(at, equals).trim();
    at = equals + 1;
    while (line[at] === " ") at++;
    let value = "";
    if (line[at] === '"') {
      for (at++; at < line.length && line[at] !== '"'; at++) {
        if (line[at] === "\\" && at + 1 < line.length) at++;
        value += line[at];
      }
      at++; // the closing quote
    } else {
      const start = at;
      for (let depth = 0; at < line.length && (depth > 0 || line[at] !== ","); at++) {
        if (line[at] === "(") depth++;
        else if (line[at] === ")") depth--;
      }
      value = line.slice(start, at).trim();
    }
    while (at < line.length && line[at] !== ",") at++;
    at++; // the comma
    if (key) found.set(key, value);
  }
  return found;
}

/** The names in /v1/api/players' answer, by in-game name else platform account, or null for anything else. */
export function playerNames(answer: unknown): string[] | null {
  const players = (answer as { players?: unknown } | null)?.players;
  if (!Array.isArray(players)) return null;
  return players.map((player: { name?: unknown; accountName?: unknown }) => {
    const name = typeof player?.name === "string" ? player.name.trim() : "";
    return name || (typeof player?.accountName === "string" ? player.accountName.trim() : "");
  });
}

/** The file in a tar from Docker's archive endpoint: a 512-byte header, then its bytes. */
export function untar(tar: Uint8Array): string {
  const text = new TextDecoder();
  for (let at = 0; tar[at]; ) {
    const size = Number.parseInt(text.decode(tar.subarray(at + 124, at + 136)), 8);
    const type = tar[at + 156];
    if (type === 0 || type === 48) return text.decode(tar.subarray(at + 512, at + 512 + size)); // a regular file
    at += 512 + Math.ceil(size / 512) * 512; // a pax header ahead of the file
  }
  return "";
}

async function docker(path: string): Promise<Response | null> {
  try {
    const response = await fetch(`http://docker${path}`, {
      unix: DOCKER_SOCKET,
      signal: AbortSignal.timeout(DOCKER_TIMEOUT_MS),
    });
    return response.ok ? response : null;
  } catch {
    return null; // a box with no socket yet
  }
}

/** The settings file out of the app's running server container, or "". */
async function settingsThroughDocker(appId: string): Promise<string> {
  // By compose project and service, since a later copy's container is ix-palworld-2-palworld-1,
  // and the project's init container shares the project
  const labels = [`com.docker.compose.project=ix-${appId}`, "com.docker.compose.service=palworld"];
  const filters = encodeURIComponent(JSON.stringify({ label: labels }));
  const listed = (await (await docker(`/containers/json?filters=${filters}`))?.json().catch(() => null)) as
    | { Id: string }[]
    | null;
  const id = listed?.[0]?.Id;
  if (!id) return "";
  const response = await docker(`/containers/${id}/archive?path=${encodeURIComponent(SERVER_DIR + SETTINGS)}`);
  return response ? untar(new Uint8Array(await response.arrayBuffer().catch(() => new ArrayBuffer(0)))) : "";
}

async function readSettings(ctx: WidgetContext): Promise<Map<string, string>> {
  const mount = serverMount(ctx.mounts);
  if (mount) {
    try {
      return optionSettings(readFileSync(mount.localPath + SETTINGS, "utf-8"));
    } catch {
      // Not written yet, or the dataset isn't visible from here
    }
  }
  return optionSettings(await settingsThroughDocker(ctx.appId));
}

/** One answer of the server's REST API, or null when it can't be reached, refuses the password, or doesn't answer in time. */
async function api(base: string, authorization: string, path: string): Promise<unknown> {
  try {
    const response = await fetch(`${base}/v1/api/${path}`, {
      headers: { Authorization: authorization, Accept: "application/json" },
      signal: AbortSignal.timeout(API_TIMEOUT_MS),
    });
    return response.ok ? await response.json() : null;
  } catch {
    return null;
  }
}

/** Who's online in a line: "Alex, Steve, and 3 more", as every game card says it. */
export function playersLine(names: string[]): string {
  if (names.length <= 2) return names.join(" and ");
  if (names.length === 3) return `${names[0]}, ${names[1]}, and ${names[2]}`;
  return `${names[0]}, ${names[1]}, and ${names.length - 2} more`;
}

export async function run(ctx: WidgetContext): Promise<WidgetQueryResult> {
  const settings = await readSettings(ctx);
  const password = settings.get("AdminPassword") ?? "";
  const enabled = settings.get("RESTAPIEnabled")?.toLowerCase() === "true";
  const port = Number(settings.get("RESTAPIPort")) || ctx.port || DEFAULT_REST_PORT;
  const base = `http://${ctx.host.includes(":") ? `[${ctx.host}]` : ctx.host}:${port}`;
  const authorization = `Basic ${Buffer.from(`admin:${password}`).toString("base64")}`;
  const [players, metrics] =
    enabled && password
      ? await Promise.all([api(base, authorization, "players"), api(base, authorization, "metrics")])
      : [null, null];
  const names = playerNames(players) ?? [];
  const max =
    Number((metrics as { maxplayernum?: unknown } | null)?.maxplayernum) || Number(settings.get("ServerPlayerMaxNum")) || 0;
  const title = settings.get("ServerName")?.trim() || "Palworld";
  // A player still loading in may have no name yet: they count, and the line names the rest
  const named = names.filter(Boolean);
  const fields: Record<string, WidgetFieldValue> = {
    // One entry while anyone's on: the server's name in bold, the players in the small line under it
    online: {
      type: "list",
      entries: names.length
        ? [{ title, ...(named.length ? { subtitle: playersLine(named) } : {}), image: ARTWORK }]
        : [],
    },
    count: { type: "stat", label: "Players", value: max > 0 ? `${names.length}/${max}` : `${names.length}` },
  };
  return { fields };
}

// Palworld's key art, from Aaron (2026-11-07): cropped to the card's shape at the size a retina screen draws it (660x260), in WebP.
export const ARTWORK =
  "data:image/webp;base64,";
